export interface ConnectorConfig {
  /** Slack Bot Token with chat:write scope. Env: SLACK_BOT_TOKEN */
  slackBotToken: string;
  /** Calendly webhook secret used to verify HMAC signature. Provided when creating the webhook subscription. */
  calendlyWebhookSecret: string;
  /** Slack channel ID (e.g., C01JASD6802) where the message will be posted. */
  slackChannel: string;
  /** Injected fetch implementation (for testing or non-standard environments). */
  fetch?: typeof fetch;
  /**
   * Optional custom verification function for the Calendly webhook signature.
   * Receives (rawBody, signatureHeader, secret) and returns a promise resolving to true if valid.
   * If not provided, and rawWebhookBody + calendlySignatureHeader are given, the built-in Web Crypto verifier is attempted.
   */
  verifyWebhookSignature?: (
    rawBody: string,
    signatureHeader: string,
    secret: string
  ) => Promise<boolean>;
  /** Raw webhook request body (string) for signature verification. */
  rawWebhookBody?: string;
  /** Value of the Calendly-Webhook-Signature header. */
  calendlySignatureHeader?: string;
}

export interface CalendlyInvitee {
  uri: string;
  email: string;
  name: string;
  status: string;
  timezone: string;
  event: string;
  created_at: string;
  updated_at: string;
  cancel_url: string;
  reschedule_url: string;
  questions_and_answers: Array<{
    question: string;
    answer: string;
    position: number;
  }>;
  tracking: Record<string, string>;
}

export interface CalendlyWebhookPayload {
  event: string;
  created_at: string;
  created_by: string;
  payload: CalendlyInvitee;
}

export type InputPayload = CalendlyWebhookPayload;

export interface HandleResult {
  slackMessageTs: string;
  slackChannel: string;
}

const SLACK_API_URL = 'https://slack.com/api/chat.postMessage';

async function verifySignatureBuiltIn(
  secret: string,
  rawBody: string,
  signatureHeader: string
): Promise<boolean> {
  const crypto = globalThis.crypto;
  if (!crypto || !crypto.subtle) {
    throw new Error('Web Crypto API (crypto.subtle) not available in this environment. Provide a custom verifyWebhookSignature function.');
  }
  const encoder = new TextEncoder();
  const key = await crypto.subtle.importKey(
    'raw',
    encoder.encode(secret),
    { name: 'HMAC', hash: 'SHA-256' },
    false,
    ['verify']
  );
  const signatureBytes = encoder.encode(signatureHeader);
  const dataBytes = encoder.encode(rawBody);
  return crypto.subtle.verify('HMAC', key, signatureBytes, dataBytes);
}

function formatSlackMessage(invitee: CalendlyInvitee): string {
  const lines = [
    'New Calendly meeting booked!',
    `Invitee: ${invitee.name}`,
    `Email: ${invitee.email}`,
    'Answers:',
  ];
  for (const qa of invitee.questions_and_answers) {
    lines.push(`- ${qa.question}?: ${qa.answer}`);
  }
  return lines.join('\n');
}

export async function handle(payload: InputPayload, config: ConnectorConfig): Promise<HandleResult> {
  const fetchImpl = config.fetch ?? globalThis.fetch;
  if (!fetchImpl) {
    throw new Error('No fetch implementation available. Provide config.fetch or ensure global fetch exists.');
  }

  // Validate required fields
  if (!payload || typeof payload !== 'object') {
    throw new Error('Invalid payload: expected an object');
  }
  if (payload.event !== 'invitee.created') {
    throw new Error(`Unsupported event type: ${payload.event}. Expected 'invitee.created'.`);
  }
  const invitee = payload.payload;
  if (!invitee) {
    throw new Error('Missing payload.invitee (payload.payload)');
  }
  if (!invitee.name || typeof invitee.name !== 'string') {
    throw new Error('Missing required field: invitee.name');
  }
  if (!invitee.email || typeof invitee.email !== 'string') {
    throw new Error('Missing required field: invitee.email');
  }
  if (!Array.isArray(invitee.questions_and_answers)) {
    throw new Error('Missing required field: invitee.questions_and_answers (array)');
  }

  // Verify webhook signature if configured
  if (config.verifyWebhookSignature) {
    if (!config.rawWebhookBody || !config.calendlySignatureHeader) {
      throw new Error('verifyWebhookSignature provided but rawWebhookBody or calendlySignatureHeader missing');
    }
    const valid = await config.verifyWebhookSignature(
      config.rawWebhookBody,
      config.calendlySignatureHeader,
      config.calendlyWebhookSecret
    );
    if (!valid) {
      throw new Error('Calendly webhook signature verification failed');
    }
  } else if (config.rawWebhookBody && config.calendlySignatureHeader) {
    const valid = await verifySignatureBuiltIn(
      config.calendlyWebhookSecret,
      config.rawWebhookBody,
      config.calendlySignatureHeader
    );
    if (!valid) {
      throw new Error('Calendly webhook signature verification failed');
    }
  }
  // If no verification config provided, skip (assume upstream verification)

  const text = formatSlackMessage(invitee);

  const response = await fetchImpl(SLACK_API_URL, {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${config.slackBotToken}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({
      channel: config.slackChannel,
      text,
    }),
  });

  if (!response.ok) {
    const errorText = await response.text().catch(() => '');
    throw new Error(
      `Slack API error: ${response.status} ${response.statusText} at ${SLACK_API_URL} - ${errorText}`
    );
  }

  const data = (await response.json()) as { ok: boolean; channel: string; ts: string };
  if (!data.ok) {
    throw new Error(`Slack API returned ok=false: ${JSON.stringify(data)}`);
  }

  return {
    slackMessageTs: data.ts,
    slackChannel: data.channel,
  };
}

import { describe, it, expect, vi } from 'vitest';
import { handle, ConnectorConfig, InputPayload, HandleResult } from './connector';
import {
  SOURCE_EXAMPLE,
  TARGET_ENDPOINTS,
  contractFetch,
  fakeFetch,
  jsonResponse,
  RecordedCall,
} from './fixtures';

describe('contract', () => {
  it('handles the documented example payload', async () => {
    const { fetch, calls } = contractFetch();
    const config: ConnectorConfig = {
      slackBotToken: 'xoxb-test-token',
      calendlyWebhookSecret: 'test-secret',
      slackChannel: 'C01JASD6802',
      fetch,
    };
    const result = await handle(SOURCE_EXAMPLE as unknown as InputPayload, config);
    expect(calls.length).toBeGreaterThan(0);
    expect(result.slackChannel).toBe('C01JASD6802');
    expect(result.slackMessageTs).toBe('1705317000.123456');
  });
});

describe('handle', () => {
  it('posts formatted message to Slack with correct field mapping', async () => {
    const { fetch, calls } = fakeFetch((req: RecordedCall) => {
      expect(req.method).toBe('POST');
      expect(req.url).toBe('https://slack.com/api/chat.postMessage');
      expect(req.headers.get('authorization')).toBe('Bearer xoxb-test-token');
      expect(req.json).toEqual({
        channel: 'C01JASD6802',
        text: 'New Calendly meeting booked!\nInvitee: Jane Doe\nEmail: jane@example.com\nAnswers:\n- What is your company?: Acme Corp\n- What is your role?: Engineer',
      });
      return jsonResponse({ ok: true, channel: 'C01JASD6802', ts: '1705317000.123456' });
    });

    const config: ConnectorConfig = {
      slackBotToken: 'xoxb-test-token',
      calendlyWebhookSecret: 'secret',
      slackChannel: 'C01JASD6802',
      fetch,
    };

    const result = await handle(SOURCE_EXAMPLE as unknown as InputPayload, config);
    expect(result).toEqual({ slackMessageTs: '1705317000.123456', slackChannel: 'C01JASD6802' });
    expect(calls.length).toBe(1);
  });

  it('uses Bearer token authentication from config', async () => {
    const { fetch, calls } = fakeFetch((req: RecordedCall) => {
      expect(req.headers.get('authorization')).toBe('Bearer xoxb-different-token');
      return jsonResponse({ ok: true, channel: 'C01JASD6802', ts: '123' });
    });

    const config: ConnectorConfig = {
      slackBotToken: 'xoxb-different-token',
      calendlyWebhookSecret: 'secret',
      slackChannel: 'C01JASD6802',
      fetch,
    };

    await handle(SOURCE_EXAMPLE as unknown as InputPayload, config);
    expect(calls[0].headers.get('authorization')).toBe('Bearer xoxb-different-token');
  });

  it('throws descriptive error when invitee.name is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({ ok: true }, 200));
    const payload = {
      ...SOURCE_EXAMPLE,
      payload: { ...SOURCE_EXAMPLE.payload, name: undefined },
    } as unknown as InputPayload;

    const config: ConnectorConfig = {
      slackBotToken: 'xoxb-test',
      calendlyWebhookSecret: 'secret',
      slackChannel: 'C01JASD6802',
      fetch,
    };

    await expect(handle(payload, config)).rejects.toThrow('Missing required field: invitee.name');
  });

  it('throws descriptive error when invitee.email is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({ ok: true }, 200));
    const payload = {
      ...SOURCE_EXAMPLE,
      payload: { ...SOURCE_EXAMPLE.payload, email: undefined },
    } as unknown as InputPayload;

    const config: ConnectorConfig = {
      slackBotToken: 'xoxb-test',
      calendlyWebhookSecret: 'secret',
      slackChannel: 'C01JASD6802',
      fetch,
    };

    await expect(handle(payload, config)).rejects.toThrow('Missing required field: invitee.email');
  });

  it('throws descriptive error when questions_and_answers is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({ ok: true }, 200));
    const payload = {
      ...SOURCE_EXAMPLE,
      payload: { ...SOURCE_EXAMPLE.payload, questions_and_answers: undefined },
    } as unknown as InputPayload;

    const config: ConnectorConfig = {
      slackBotToken: 'xoxb-test',
      calendlyWebhookSecret: 'secret',
      slackChannel: 'C01JASD6802',
      fetch,
    };

    await expect(handle(payload, config)).rejects.toThrow('Missing required field: invitee.questions_and_answers (array)');
  });

  it('throws error with status code and endpoint on non-2xx Slack response', async () => {
    const { fetch, calls } = fakeFetch(() => jsonResponse({ error: 'channel_not_found' }, 404));

    const config: ConnectorConfig = {
      slackBotToken: 'xoxb-test',
      calendlyWebhookSecret: 'secret',
      slackChannel: 'C01JASD6802',
      fetch,
    };

    await expect(handle(SOURCE_EXAMPLE as unknown as InputPayload, config)).rejects.toThrow(
      'Slack API error: 404 Not Found at https://slack.com/api/chat.postMessage'
    );
    expect(calls.length).toBe(1);
  });

  it('throws error when Slack returns ok=false', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({ ok: false, error: 'invalid_auth' }, 200));

    const config: ConnectorConfig = {
      slackBotToken: 'xoxb-test',
      calendlyWebhookSecret: 'secret',
      slackChannel: 'C01JASD6802',
      fetch,
    };

    await expect(handle(SOURCE_EXAMPLE as unknown as InputPayload, config)).rejects.toThrow(
      'Slack API returned ok=false'
    );
  });

  it('verifies webhook signature when custom verifier provided', async () => {
    let verifyCalled = false;
    const { fetch, calls } = fakeFetch((req) => {
      verifyCalled = true;
      return jsonResponse({ ok: true, channel: 'C01JASD6802', ts: '123' });
    });

    const config: ConnectorConfig = {
      slackBotToken: 'xoxb-test',
      calendlyWebhookSecret: 'secret',
      slackChannel: 'C01JASD6802',
      fetch,
      verifyWebhookSignature: async (body, sig, secret) => {
        expect(body).toBe('raw-body');
        expect(sig).toBe('sig-header');
        expect(secret).toBe('secret');
        return true;
      },
      rawWebhookBody: 'raw-body',
      calendlySignatureHeader: 'sig-header',
    };

    const result = await handle(SOURCE_EXAMPLE as unknown as InputPayload, config);
    expect(verifyCalled).toBe(true);
    expect(result.slackChannel).toBe('C01JASD6802');
  });

  it('throws when custom verifier returns false', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({ ok: true }, 200));

    const config: ConnectorConfig = {
      slackBotToken: 'xoxb-test',
      calendlyWebhookSecret: 'secret',
      slackChannel: 'C01JASD6802',
      fetch,
      verifyWebhookSignature: async () => false,
      rawWebhookBody: 'raw-body',
      calendlySignatureHeader: 'sig-header',
    };

    await expect(handle(SOURCE_EXAMPLE as unknown as InputPayload, config)).rejects.toThrow(
      'Calendly webhook signature verification failed'
    );
  });

  it('skips signature verification when no verification config provided', async () => {
    const { fetch, calls } = fakeFetch((req) => jsonResponse({ ok: true, channel: 'C01JASD6802', ts: '123' }));

    const config: ConnectorConfig = {
      slackBotToken: 'xoxb-test',
      calendlyWebhookSecret: 'secret',
      slackChannel: 'C01JASD6802',
      fetch,
      // No verifyWebhookSignature, no rawWebhookBody
    };

    const result = await handle(SOURCE_EXAMPLE as unknown as InputPayload, config);
    expect(calls.length).toBe(1);
    expect(result.slackChannel).toBe('C01JASD6802');
  });
});

# Calendly to Slack Connector

Posts a formatted message to a Slack channel when a Calendly meeting is booked via the `invitee.created` webhook.

## What it does

1. Receives a Calendly webhook payload (the `invitee.created` event).
2. Validates required fields: invitee name, email, and custom questionnaire answers.
3. Optionally verifies the webhook HMAC signature using the secret from the webhook subscription.
4. Formats the invitee data into a readable text block.
5. Sends the message to the specified Slack channel using `chat.postMessage`.

## Configuration / Environment Variables

| Config Property | Environment Variable | Description |
|-----------------|---------------------|-------------|
| `slackBotToken` | `SLACK_BOT_TOKEN` | Slack Bot User OAuth token with `chat:write` scope. |
| `calendlyWebhookSecret` | `CALENDLY_WEBHOOK_SECRET` | Secret provided when creating the Calendly webhook subscription. Used to verify the `Calendly-Webhook-Signature` header. |
| `slackChannel` | `SLACK_CHANNEL_ID` | The Slack channel ID (e.g., `C01JASD6802`) where messages will be posted. |
| `fetch` | — | Optional injected `fetch` implementation (for testing or non-standard runtimes). |
| `verifyWebhookSignature` | — | Optional custom async function `(rawBody, signatureHeader, secret) => Promise<boolean>` for signature verification. |
| `rawWebhookBody` | — | Raw webhook request body string (for built-in verification). |
| `calendlySignatureHeader` | — | Value of the `Calendly-Webhook-Signature` header (for built-in verification). |

## Usage Example

```typescript
import { handle, ConnectorConfig } from './connector';

// In your webhook handler (e.g., Cloudflare Worker, Express, etc.):
export default {
  async fetch(request: Request, env: Env) {
    // 1. Verify signature at the edge (recommended) or pass raw body to connector
    const rawBody = await request.text();
    const signature = request.headers.get('Calendly-Webhook-Signature') ?? '';
    // ... verify using env.CALENDLY_WEBHOOK_SECRET ...

    // 2. Parse JSON
    const payload = JSON.parse(rawBody);

    // 3. Call connector
    const config: ConnectorConfig = {
      slackBotToken: env.SLACK_BOT_TOKEN,
      calendlyWebhookSecret: env.CALENDLY_WEBHOOK_SECRET,
      slackChannel: env.SLACK_CHANNEL_ID,
      // Optionally pass raw body + signature for connector-side verification:
      // rawWebhookBody: rawBody,
      // calendlySignatureHeader: signature,
    };

    const result = await handle(payload, config);
    return Response.json({ success: true, slackTs: result.slackMessageTs });
  },
};
```

## Assumptions

- The Calendly event has associated custom questionnaire questions and answers enabled (the `questions_and_answers` array is present in the webhook payload).
- The Slack channel ID is known and provided via configuration.
- The integration formats the invitee data into a readable message block for Slack (plain text fallback; no Block Kit used).
- Webhook signature verification is performed either upstream (at the webhook receiver) or by the connector when `rawWebhookBody` and `calendlySignatureHeader` are supplied. The built-in verifier requires the Web Crypto API (`crypto.subtle`); if unavailable, provide a custom `verifyWebhookSignature` function.
- The Calendly webhook payload structure matches the documented example (invitee fields at `payload.name`, `payload.email`, `payload.questions_and_answers`).
- Slack Bot Token has the `chat:write` scope and access to the target channel.

