export interface DocumentedEndpoint {
  method: string
  /** As documented; may contain placeholders such as {id}, :id, <id> or a region host like usX. */
  url: string
  response: unknown
}

/** Target endpoints the connector may call, in the documented order, with their documented responses. */
export const TARGET_ENDPOINTS: DocumentedEndpoint[] = [
  {
    "method": "POST",
    "url": "https://slack.com/api/chat.postMessage",
    "response": {
      "ok": true,
      "channel": "C01JASD6802",
      "ts": "1705317000.123456"
    }
  }
]

export interface RecordedCall {
  method: string
  url: string
  /** The request body exactly as sent (usually a JSON string). */
  body: string | undefined
  /** The body parsed as JSON, or undefined when it is not JSON. */
  json: unknown
  headers: Headers
}

/** The documented endpoint a request matches, placeholders and region subdomains included. */
export function findEndpoint(method: string, url: string): DocumentedEndpoint | undefined {
  return TARGET_ENDPOINTS.find((endpoint) => endpoint.method === method.toUpperCase() && urlMatches(endpoint.url, url))
}

/**
 * A fake fetch that answers every documented endpoint with its documented response and
 * rejects anything else. Use it in the contract test:
 *
 *   const { fetch, calls } = contractFetch()
 *   await handle(SOURCE_EXAMPLE as MyInput, { ...config, fetch })
 *   expect(calls.length).toBeGreaterThan(0)
 */
export function contractFetch(): { fetch: typeof fetch; calls: RecordedCall[] } {
  return fakeFetch((request) => {
    const endpoint = findEndpoint(request.method, request.url)
    if (!endpoint) throw new Error(`contract: ${request.method} ${request.url} is not a documented endpoint`)
    return jsonResponse(endpoint.response)
  })
}

/**
 * A correctly typed fake fetch for every other test. The handler receives the recorded
 * request: { method, url, body (string as sent), json (parsed body), headers (Headers) }.
 *
 *   const { fetch, calls } = fakeFetch((req) => req.url.endsWith('/deals') ? jsonResponse({ id: 1 }, 201) : jsonResponse({}, 404))
 */
export function fakeFetch(
  handler: (request: RecordedCall) => Response | Promise<Response>,
): { fetch: typeof fetch; calls: RecordedCall[] } {
  const calls: RecordedCall[] = []
  const fake = async (input: string | URL | Request, init: RequestInit = {}): Promise<Response> => {
    const url = input instanceof Request ? input.url : String(input)
    const method = (init.method ?? (input instanceof Request ? input.method : 'GET')).toUpperCase()
    const body = typeof init.body === 'string' ? init.body : init.body == null ? undefined : String(init.body)
    const call: RecordedCall = { method, url, body, json: parseJson(body), headers: new Headers(init.headers) }
    calls.push(call)
    return handler(call)
  }
  return { fetch: fake as typeof fetch, calls }
}

const STATUS_TEXT: Record<number, string> = {
  200: 'OK', 201: 'Created', 202: 'Accepted', 204: 'No Content',
  400: 'Bad Request', 401: 'Unauthorized', 403: 'Forbidden', 404: 'Not Found', 409: 'Conflict',
  422: 'Unprocessable Entity', 429: 'Too Many Requests',
  500: 'Internal Server Error', 502: 'Bad Gateway', 503: 'Service Unavailable',
}

/** A JSON Response with the standard status text, e.g. jsonResponse({ error: 'nope' }, 401) -> "401 Unauthorized". */
export function jsonResponse(body: unknown, status = 200): Response {
  const init = { status, statusText: STATUS_TEXT[status] ?? '', headers: { 'Content-Type': 'application/json' } }
  return new Response(status === 204 ? null : JSON.stringify(body), init)
}

function parseJson(raw: string | undefined): unknown {
  if (raw === undefined) return undefined
  try {
    return JSON.parse(raw)
  } catch {
    return undefined
  }
}

function urlMatches(template: string, actual: string): boolean {
  const t = splitUrl(template)
  const a = splitUrl(actual)
  if (!t || !a) return false
  const tHost = t.host.split('.')
  const aHost = a.host.split('.')
  if (tHost.slice(-2).join('.') !== aHost.slice(-2).join('.')) return false
  const tPath = t.path.replace(/\/+$/, '').split('/')
  const aPath = a.path.replace(/\/+$/, '').split('/')
  if (tPath.length !== aPath.length) return false
  return tPath.every((segment, i) => isPlaceholder(segment) || segment === aPath[i])
}

function splitUrl(url: string): { host: string; path: string } | null {
  const match = url.match(/^https?:\/\/([^/?#]+)([^?#]*)/i)
  return match ? { host: (match[1] ?? '').toLowerCase(), path: match[2] || '/' } : null
}

function isPlaceholder(segment: string): boolean {
  return /^\{[^}]+\}$|^:[A-Za-z_]\w*$|^<[^>]+>$/.test(segment)
}

export interface ConnectorConfig {
  /** Slack Bot Token with chat:write scope. Env: SLACK_BOT_TOKEN */
  slackBotToken: string;
  /** Calendly webhook secret used to verify HMAC signature. Provided when creating the webhook subscription. */
  calendlyWebhookSecret: string;
  /** Slack channel ID (e.g., C01JASD6802) where the message will be posted. */
  slackChannel: string;
  /** Injected fetch implementation (for testing or non-standard environments). */
  fetch?: typeof fetch;
  /**
   * Optional custom verification function for the Calendly webhook signature.
   * Receives (rawBody, signatureHeader, secret) and returns a promise resolving to true if valid.
   * If not provided, and rawWebhookBody + calendlySignatureHeader are given, the built-in Web Crypto verifier is attempted.
   */
  verifyWebhookSignature?: (
    rawBody: string,
    signatureHeader: string,
    secret: string
  ) => Promise<boolean>;
  /** Raw webhook request body (string) for signature verification. */
  rawWebhookBody?: string;
  /** Value of the Calendly-Webhook-Signature header. */
  calendlySignatureHeader?: string;
}

export interface CalendlyInvitee {
  uri: string;
  email: string;
  name: string;
  status: string;
  timezone: string;
  event: string;
  created_at: string;
  updated_at: string;
  cancel_url: string;
  reschedule_url: string;
  questions_and_answers: Array<{
    question: string;
    answer: string;
    position: number;
  }>;
  tracking: Record<string, string>;
}

export interface CalendlyWebhookPayload {
  event: string;
  created_at: string;
  created_by: string;
  payload: CalendlyInvitee;
}

export type InputPayload = CalendlyWebhookPayload;

export interface HandleResult {
  slackMessageTs: string;
  slackChannel: string;
}

const SLACK_API_URL = 'https://slack.com/api/chat.postMessage';

async function verifySignatureBuiltIn(
  secret: string,
  rawBody: string,
  signatureHeader: string
): Promise<boolean> {
  const crypto = globalThis.crypto;
  if (!crypto || !crypto.subtle) {
    throw new Error('Web Crypto API (crypto.subtle) not available in this environment. Provide a custom verifyWebhookSignature function.');
  }
  const encoder = new TextEncoder();
  const key = await crypto.subtle.importKey(
    'raw',
    encoder.encode(secret),
    { name: 'HMAC', hash: 'SHA-256' },
    false,
    ['verify']
  );
  const signatureBytes = encoder.encode(signatureHeader);
  const dataBytes = encoder.encode(rawBody);
  return crypto.subtle.verify('HMAC', key, signatureBytes, dataBytes);
}

function formatSlackMessage(invitee: CalendlyInvitee): string {
  const lines = [
    'New Calendly meeting booked!',
    `Invitee: ${invitee.name}`,
    `Email: ${invitee.email}`,
    'Answers:',
  ];
  for (const qa of invitee.questions_and_answers) {
    lines.push(`- ${qa.question}: ${qa.answer}`);
  }
  return lines.join('\n');
}

export async function handle(payload: InputPayload, config: ConnectorConfig): Promise<HandleResult> {
  const fetchImpl = config.fetch ?? globalThis.fetch;
  if (!fetchImpl) {
    throw new Error('No fetch implementation available. Provide config.fetch or ensure global fetch exists.');
  }

  // Validate required fields
  if (!payload || typeof payload !== 'object') {
    throw new Error('Invalid payload: expected an object');
  }
  if (payload.event !== 'invitee.created') {
    throw new Error(`Unsupported event type: ${payload.event}. Expected 'invitee.created'.`);
  }
  const invitee = payload.payload;
  if (!invitee) {
    throw new Error('Missing payload.invitee (payload.payload)');
  }
  if (!invitee.name || typeof invitee.name !== 'string') {
    throw new Error('Missing required field: invitee.name');
  }
  if (!invitee.email || typeof invitee.email !== 'string') {
    throw new Error('Missing required field: invitee.email');
  }
  if (!Array.isArray(invitee.questions_and_answers)) {
    throw new Error('Missing required field: invitee.questions_and_answers (array)');
  }

  // Verify webhook signature if configured
  if (config.verifyWebhookSignature) {
    if (!config.rawWebhookBody || !config.calendlySignatureHeader) {
      throw new Error('verifyWebhookSignature provided but rawWebhookBody or calendlySignatureHeader missing');
    }
    const valid = await config.verifyWebhookSignature(
      config.rawWebhookBody,
      config.calendlySignatureHeader,
      config.calendlyWebhookSecret
    );
    if (!valid) {
      throw new Error('Calendly webhook signature verification failed');
    }
  } else if (config.rawWebhookBody && config.calendlySignatureHeader) {
    const valid = await verifySignatureBuiltIn(
      config.calendlyWebhookSecret,
      config.rawWebhookBody,
      config.calendlySignatureHeader
    );
    if (!valid) {
      throw new Error('Calendly webhook signature verification failed');
    }
  }
  // If no verification config provided, skip (assume upstream verification)

  const text = formatSlackMessage(invitee);

  const response = await fetchImpl(SLACK_API_URL, {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${config.slackBotToken}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({
      channel: config.slackChannel,
      text,
    }),
  });

  if (!response.ok) {
    const errorText = await response.text().catch(() => '');
    throw new Error(
      `Slack API error: ${response.status} ${response.statusText} at ${SLACK_API_URL} - ${errorText}`
    );
  }

  const data = (await response.json()) as { ok: boolean; channel: string; ts: string };
  if (!data.ok) {
    throw new Error(`Slack API returned ok=false: ${JSON.stringify(data)}`);
  }

  return {
    slackMessageTs: data.ts,
    slackChannel: data.channel,
  };
}

